// VRG Mobile for the iPhone (WP M36): the online part of VRG Mobile as a web app, because an iPhone cannot install the
// Android APK and Safari has no Bluetooth (so Csipogó, Légegér and the BLE features stay Android-only). The same
// palettes and Varler mark as the app (generated by Mobile/catalogue/icon-gen.js), the same device approval as
// Eszközök (M35), Haladás from GitHub, and an update that waits for approval when the release lock is on.
import { MARK } from './mark.js';
import { qrSvg } from './qr.js';
import * as D from './device.js';

const REPO = 'webagoly-work/vrg-toolset';
const API = 'https://api.github.com/repos/' + REPO;
const TRUST = `https://raw.githubusercontent.com/${REPO}/main/Mobile/trust/devices.json`;
const $ = (s, el = document) => el.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const view = $('#view');
let VERSION = { v: 'helyi', at: '' };
let PALETTES = null;

// ---- look: the palettes of the app ------------------------------------------------------------------------------
async function applyPalette(id) {
  PALETTES = PALETTES || await fetch('palettes.json').then(r => r.json());
  const p = PALETTES.palettes.find(x => x.id === id) || PALETTES.palettes.find(x => x.id === PALETTES.default);
  const r = document.documentElement.style;
  for (const [k, v] of Object.entries(p.colors)) r.setProperty('--' + k, v);
  document.documentElement.dataset.light = p.light ? '1' : '0';
  $('meta[name=theme-color]').setAttribute('content', p.colors.abyss);
  // the home-screen icon iOS takes when "Add to Home Screen" is pressed: this palette's
  $('link[rel=apple-touch-icon]').setAttribute('href', `icons/touch-${p.id}.png`);
  D.LS.set('palette', p.id);
  return p;
}

const markSvg = cls => `<svg class="${cls}" viewBox="${MARK.box.join(' ')}" aria-hidden="true"><path fill="currentColor" fill-rule="evenodd" d="${MARK.d}"/></svg>`;

// ---- trust list --------------------------------------------------------------------------------------------------
let TRUST_LIST = null;
async function trust(force) {
  if (TRUST_LIST && !force) return TRUST_LIST;
  try { const r = await fetch(TRUST + '?t=' + Math.floor(Date.now() / 60000), { cache: 'no-store' }); if (r.ok) TRUST_LIST = await r.json(); } catch (e) { /* offline */ }
  if (!TRUST_LIST) { try { TRUST_LIST = JSON.parse(D.LS.get('trust') || 'null'); } catch (e) { /* none */ } }
  if (TRUST_LIST) D.LS.set('trust', JSON.stringify(TRUST_LIST));
  return TRUST_LIST;
}
const listed = t => !!t && (t.devices || []).some(d => D.sameId(d.id, D.deviceId()));
const updatesAllowed = t => !t || !t.gated || listed(t);

// ---- GitHub ------------------------------------------------------------------------------------------------------
async function gh(path) {
  const tok = D.LS.get('gh.token'), h = { Accept: 'application/vnd.github+json' };
  if (tok) h.Authorization = 'Bearer ' + tok;
  const r = await fetch(API + path, { headers: h });
  if (r.status === 403 && r.headers.get('x-ratelimit-remaining') === '0') throw new Error('A GitHub óránként 60 kérést enged belépés nélkül. Később újra, vagy kérj engedélyt tokennel.');
  if (!r.ok) throw new Error('GitHub ' + r.status);
  return r.json();
}

// ---- the iPhone guide (guide/iphone.json: the one source the Android app bundles too) --------------------------
let GUIDE = null;
async function guide() { return GUIDE || (GUIDE = await fetch('guide/iphone.json').then(r => r.json()).catch(() => null)); }

/** Safari or the home-screen app: they keep separate storage, and the guide says which one this is. */
const standalone = () => window.navigator.standalone === true || window.matchMedia('(display-mode: standalone)').matches;
const WHO = { iphone: 'az iPhone-on', owner: 'a tulajdonos Android telefonján', both: '' };

function guideHtml(g, opts = {}) {
  if (!g) return '<p class="hint">Az útmutató most nem tölthető be (offline?).</p>';
  const here = standalone() ? 'Most a kezdőképernyőre tett appban vagy.' : 'Most a Safariban vagy.';
  return `<div class="guide">
    ${opts.title === false ? '' : `<h2>${esc(g.title)}</h2>`}
    <p>${esc(g.intro)}</p>
    ${g.sections.map(sec => `<section class="gsec" id="g-${esc(sec.id)}">
      <h3>${esc(sec.title)}${WHO[sec.who] ? ` <span class="who ${esc(sec.who)}">${esc(WHO[sec.who])}</span>` : ''}</h3>
      ${sec.id === 'where' ? `<p class="here">${esc(here)}</p>` : ''}
      ${sec.steps ? `<ol>${sec.steps.map(st => `<li>${esc(st)}</li>`).join('')}</ol>` : ''}
      ${sec.faq ? `<dl>${sec.faq.map(f => `<dt>${esc(f.q)}</dt><dd>${esc(f.a)}</dd>`).join('')}</dl>` : ''}
    </section>`).join('')}
  </div>`;
}

async function utmutato() { view.innerHTML = guideHtml(await guide()); }

// ---- screens -----------------------------------------------------------------------------------------------------
const TILES = [
  { id: 'eszkoz', glyph: '🔐', t: 'Eszköz', s: 'Hozzáférés kérése QR-kóddal' },
  { id: 'haladas', glyph: '📈', t: 'Haladás', s: 'Commitok, PR-ek, CI a main ágon' },
  { id: 'frissites', glyph: '⟳', t: 'Frissítés', s: 'A webapp új verziója' },
  { id: 'megjelenes', glyph: '🎨', t: 'Megjelenés', s: 'A VRG Mobile palettái' },
];
const ANDROID_ONLY = ['Csipogó', 'Légegér', 'Képernyő', 'Átadás', 'Hálózat'];

function home() {
  const tl = TRUST_LIST || (() => { try { return JSON.parse(D.LS.get('trust') || 'null'); } catch (e) { return null; } })();
  const guideCard = listed(tl) ? '' : `<a class="tile wide" href="#/utmutato"><span class="g">📱</span><b>iPhone csatlakoztatása</b><small>Lépésről lépésre: hogyan kérj hozzáférést és hogyan hagyja jóvá a tulajdonos (kb. 3 perc)</small></a>`;
  view.innerHTML = `${guideCard}
    <section class="tiles">${TILES.map(t => `<a class="tile" href="#/${t.id}"><span class="g">${t.glyph}</span><b>${t.t}</b><small>${t.s}</small></a>`).join('')}</section>
    <p class="hint">Csak Androidon (Bluetooth vagy a PC reléje kell hozzájuk, ami iPhone böngészőben nem elérhető): ${ANDROID_ONLY.join(', ')}.</p>`;
}

async function eszkoz() {
  const t = await trust(true), id = D.deviceId(), granted = D.LS.get('device.granted');
  const st = !t ? 'A lista nem olvasható (nincs internet?).' : listed(t) ? 'Jóváhagyott eszköz' + (granted ? ': ' + granted : '.') : 'Nincs a megbízható eszközök között.';
  view.innerHTML = `
    <h2>Eszköz</h2>
    <p class="hint">Egy fiók (a tulajdonosé), az eszközök különböznek: ezt a telefont a tulajdonos Android telefonja hagyja jóvá, QR-kóddal.</p>
    <div class="card"><small>Eszköz azonosító</small><div class="code">${esc(id)}</div>
      <div class="${listed(t) ? 'ok' : 'warn'}">${esc(st)}</div>
      ${t && t.gated ? `<div class="hint">${updatesAllowed(t) ? 'Frissítést kaphat.' : 'Frissítést csak jóváhagyás után kap (a kiadások zárolva).'}</div>` : ''}
      <label class="field">A telefon neve a listán <input id="nm" value="${esc(D.deviceName())}" maxlength="40"></label>
    </div>
    <details class="gbox"${listed(t) ? '' : ' open'}><summary>Részletes útmutató: így csatlakoztasd az iPhone-t</summary>${guideHtml(await guide(), { title: false })}</details>
    <h3>Hozzáférés kérése</h3>
    <button id="req" class="pri">Kérés QR-kódja</button>
    <div id="reqbox"></div>
    <div id="wait"></div>
    <h3>Engedély (nem mindig kell)</h3>
    <p class="hint">Ha a tulajdonos a saját telefonjával olvasta be a kérésedet, az iPhone magától feloldódik, nem kell engedély. Engedély QR akkor kell, ha írási jogot is kapsz, vagy ha nem akarsz várni. Safariban olvasd be a Kamerával; a kezdőképernyőre tett appban másold be ide az üzenetet (a két változat külön tárolót használ).</p>
    <textarea id="paste" rows="3" placeholder="Engedély link vagy üzenet…"></textarea>
    <button id="acc">Engedély beillesztése</button>
    <div id="accmsg"></div>`;
  $('#nm').onchange = e => D.setDeviceName(e.target.value);
  $('#req').onclick = async () => {
    const r = await D.makeRequest(VERSION.v);
    $('#reqbox').innerHTML = `<div class="qr">${qrSvg(r.link, { ecc: 'M' })}</div>
      <div class="code big">${esc(r.code)}</div>
      <p class="hint">Mutasd a képernyőt a tulajdonosnak: ő a VRG Mobile QR beolvasásával beolvassa, és a telefonja azonnal jóváhagyja. Üzenetben küldött kérésnél ugyanezt a kódot kell látnia. Hagyd nyitva ezt az oldalt.</p>
      <button id="share">Megosztás (üzenetben)</button>`;
    waitForApproval();
    $('#share').onclick = () => (navigator.share ? navigator.share({ text: `VRG Mobile hozzáférés-kérés (${r.req.name}, kód ${r.code}):\n${r.link}` }) : navigator.clipboard.writeText(r.link)).catch(() => {});
  };
  $('#acc').onclick = () => accept($('#paste').value, $('#accmsg'));
}

/** While this page is open and the device is not on the list: read the list every 10 s and say when it is (D-46). */
let waiting = null;
function waitForApproval() {
  if (waiting) return;
  const box = $('#wait'), started = Date.now();
  const tick = async () => {
    if (!location.hash.startsWith('#/eszkoz')) { clearInterval(waiting); waiting = null; return; }
    const t = await trust(true);
    const box2 = $('#wait');
    if (listed(t)) {
      clearInterval(waiting); waiting = null;
      if (box2) box2.innerHTML = '<div class="ok big">Jóváhagyva! Ez az iPhone rajta van a megbízható eszközök listáján.</div>';
      return;
    }
    const min = Math.floor((Date.now() - started) / 60000);
    if (box2) box2.innerHTML = `<p class="warn">Jóváhagyásra vár… 10 másodpercenként újranézi a listát${min >= 1 ? ` (${min} perce)` : ''}. A GitHub néha 1–5 percig a régi listát adja.</p>`;
  };
  if (box) box.innerHTML = '<p class="warn">Jóváhagyásra vár…</p>';
  waiting = setInterval(tick, 10000);
}

async function accept(text, out) {
  try {
    const g = D.readGrant(text), p = await D.acceptGrant(g);
    out.innerHTML = `<div class="ok">Engedély elfogadva: ${esc(p.by || g.by)}${p.token ? ' (írási joggal)' : ''}.</div>`;
    await trust(true);
  } catch (e) { out.innerHTML = `<div class="bad">${esc(e.message)}</div>`; }
}

async function haladas() {
  view.innerHTML = '<h2>Haladás</h2><p class="hint">A main ág friss állapota a GitHubról.</p><div id="h">Betöltés…</div>';
  try {
    const [commits, pulls, runs] = await Promise.all([gh('/commits?sha=main&per_page=12'), gh('/pulls?state=open&per_page=10'), gh('/actions/runs?per_page=6')]);
    $('#h').innerHTML = `
      <h3>Futások (CI)</h3>${runs.workflow_runs.map(r => `<div class="row"><span class="dot ${r.conclusion === 'success' ? 'ok' : r.conclusion ? 'bad' : 'run'}"></span>${esc(r.name)} · ${esc(r.head_branch)} <small>${esc((r.updated_at || '').slice(0, 16).replace('T', ' '))}</small></div>`).join('')}
      <h3>Nyitott PR-ek</h3>${pulls.length ? pulls.map(p => `<a class="row" href="${esc(p.html_url)}">#${p.number} ${esc(p.title)}</a>`).join('') : '<p class="hint">Nincs.</p>'}
      <h3>Commitok</h3>${commits.map(c => `<a class="row" href="${esc(c.html_url)}"><code>${c.sha.slice(0, 7)}</code> ${esc(c.commit.message.split('\n')[0])} <small>${esc((c.commit.author.date || '').slice(0, 10))}</small></a>`).join('')}`;
  } catch (e) { $('#h').innerHTML = `<div class="bad">${esc(e.message)}</div>`; }
}

async function frissites() {
  view.innerHTML = `<h2>Frissítés</h2><p class="hint">Fut: ${esc(VERSION.v)} ${esc(VERSION.at)}</p><div id="u">Keresés…</div>`;
  let latest = null;
  try { latest = await fetch('version.json', { cache: 'no-store' }).then(r => r.json()); } catch (e) { /* offline */ }
  const t = await trust(true), box = $('#u');
  if (!latest) { box.innerHTML = '<p class="hint">Nem érhető el (offline?). A webapp a tárolt verzióval fut.</p>'; return; }
  if (latest.v === VERSION.v) { box.innerHTML = '<p class="ok">Ez a legfrissebb verzió.</p>'; return; }
  if (!updatesAllowed(t)) {
    box.innerHTML = `<p class="warn">Új verzió: ${esc(latest.v)}. A frissítéshez jóváhagyott eszköz kell (a kiadások zárolva).</p><a class="btn pri" href="#/eszkoz">Eszköz: hozzáférés kérése ›</a>`;
    return;
  }
  box.innerHTML = `<p>Új verzió: <b>${esc(latest.v)}</b> ${esc(latest.at || '')}</p><button id="go" class="pri">Frissítés most</button>`;
  $('#go').onclick = async () => {
    const reg = await navigator.serviceWorker?.getRegistration();
    if (reg && reg.active) {
      await new Promise(ok => { navigator.serviceWorker.addEventListener('message', e => e.data === 'refreshed' && ok(), { once: true }); reg.active.postMessage('refresh'); setTimeout(ok, 15000); });
    }
    location.reload();
  };
}

async function megjelenes() {
  PALETTES = PALETTES || await fetch('palettes.json').then(r => r.json());
  const cur = D.LS.get('palette') || PALETTES.default;
  view.innerHTML = `<h2>Megjelenés</h2><p class="hint">A VRG Mobile palettái. A kezdőképernyő ikonja annak a palettának a színét kapja, amelyik a „Hozzáadás a főképernyőhöz” pillanatában be van állítva.</p>
    ${PALETTES.palettes.map(p => `<button class="pal${p.id === cur ? ' on' : ''}" data-id="${p.id}" style="background:${p.colors.surface};color:${p.colors.ink};border-color:${p.id === cur ? p.colors.glow : p.colors.line}">
      <span>${esc(p.name)}</span><span class="sw">${['abyss', 'raised', 'line', 'glow', 'current', 'sand', 'coral'].map(k => `<i style="background:${p.colors[k]}"></i>`).join('')}</span></button>`).join('')}`;
  view.querySelectorAll('.pal').forEach(b => b.onclick = async () => { await applyPalette(b.dataset.id); megjelenes(); });
}

const ROUTES = { '': home, eszkoz, haladas, frissites, megjelenes, utmutato };
function route() {
  const h = location.hash;
  if (h.startsWith('#grant=')) {                     // the owner's grant QR, opened by the iPhone's camera
    history.replaceState(null, '', '#/eszkoz');          // no hashchange: the screen must not be drawn twice
    $('#back').hidden = false;
    eszkoz().then(() => accept(h, $('#accmsg')));
    return;
  }
  const name = h.replace(/^#\/?/, '');
  $('#back').hidden = !name;
  (ROUTES[name] || home)();
}

(async () => {
  document.body.insertAdjacentHTML('afterbegin', `<div class="watermark">${markSvg('mark')}</div>`);
  $('#logo').innerHTML = markSvg('logo');
  await applyPalette(D.LS.get('palette'));
  try { VERSION = await fetch('version.json').then(r => r.json()); } catch (e) { /* local preview */ }
  $('#ver').textContent = VERSION.v;
  if ('serviceWorker' in navigator && window.isSecureContext) navigator.serviceWorker.register('sw.js').catch(() => {});
  window.addEventListener('hashchange', route);
  route();
})();
